/** Native arena screenshots plus the exact terminal API/payload path, without MCEF or OS focus. */
@EventBusSubscriber(modid="muxi_horse_racing",value=Dist.CLIENT)
public final class HorseStadiumClientQA {
    private static final net.minecraft.resources.ResourceKey<Level> SOURCE_DIMENSION=net.minecraft.resources.ResourceKey.create(Registries.DIMENSION,net.minecraft.resources.ResourceLocation.parse(System.getProperty("muxi.horse.sourceDimension","minecraft:overworld")));
    private static int ticks,stage,frames,shots;private static boolean starting,closing,done,appVerified,buildingShot;
    private static boolean admissionStalled;private static volatile boolean ready;private static volatile String error="";
    private static Horse source;private static UUID sourceId;private static volatile int horseId;
    private static final Set<String> checked=new HashSet<>();private static final JsonArray checks=new JsonArray();private static final JsonObject report=new JsonObject();
    private static final List<Double> podiumIntervals=new ArrayList<>();private static final List<Double> renderIntervals=new ArrayList<>();private static long lastRender;
    private static final boolean PERF=Boolean.getBoolean("muxi.horse.performanceQa");private static boolean captureSinceRender;private static double captureMillis;private static String model,texture;private static volatile JsonObject nativeState;
    private static void check(boolean yes,String label){if(!yes)throw new IllegalStateException(label);if(checked.add(label))checks.add(label);}
    private static void save(String name,Object value)throws Exception{Files.writeString(Path.of(name),new GsonBuilder().setPrettyPrinting().create().toJson(value));}
    private static void shot(String name)throws Exception{long captureStart=System.nanoTime();captureSinceRender=true;try(var img=Screenshot.takeScreenshot(Minecraft.getInstance().getMainRenderTarget())){img.writeToFile(Path.of(name+".png"));}captureMillis+=(System.nanoTime()-captureStart)/1e6;}
    private static void serverTask(java.util.function.Consumer<ServerPlayer> task){var mc=Minecraft.getInstance();UUID id=mc.player.getUUID();ready=false;mc.getSingleplayerServer().execute(()->{try{task.accept(mc.getSingleplayerServer().getPlayerList().getPlayer(id));ready=true;}catch(Throwable f){error=f.toString();}});}
    private static JsonObject app(){return JsonParser.parseString(TerminalGamesApi.snapshotJson()).getAsJsonObject();}
    private static JsonObject game(){for(var row:app().getAsJsonArray("games"))if(row.getAsJsonObject().get("id").getAsString().equals(HorseRooms.ID))return row.getAsJsonObject();return null;}
    private static JsonObject room(){var g=game();return g==null||g.getAsJsonObject("state").getAsJsonArray("rooms").isEmpty()?null:g.getAsJsonObject("state").getAsJsonArray("rooms").get(0).getAsJsonObject();}
    private static void next(){stage++;frames=0;}
    private static void look(double x,double y,double z,double tx,double ty,double tz){var p=Minecraft.getInstance().player;p.setPos(x,y,z);double dx=tx-x,dz=tz-z,dy=ty-y;p.setYRot((float)Math.toDegrees(Math.atan2(-dx,dz)));p.setXRot((float)-Math.toDegrees(Math.atan2(dy,Math.hypot(dx,dz))));p.setOldPosAndRot();}
    private static void close(boolean success,String reason)throws Exception{report.addProperty("success",success);report.addProperty("error",reason);report.add("checks",checks);report.addProperty("MCEF",HorseCefQA.ENABLED);report.addProperty("visualAppAcceptance",success&&HorseCefQA.ENABLED);report.addProperty("mcefShutdownGuard",System.getProperty("muxi_terminal.mcef_shutdown_guard","not-loaded"));report.addProperty("fixedPodiumPerformanceQA",PERF);report.addProperty("screenshotCaptureTotalMillis",captureMillis);HorseCefQA.close();report.addProperty("terminalApiPayloadTested",true);report.addProperty("mountedMaidDraws",HorseClientQA.mountedMaidDraws);Collections.sort(podiumIntervals);if(!podiumIntervals.isEmpty()){report.addProperty(PERF?"stablePodiumFrameP95Millis":"initialPodiumFrameP95Millis",podiumIntervals.get((int)(podiumIntervals.size()*.95)));report.addProperty(PERF?"stablePodiumFrameSamples":"initialPodiumFrameSamples",podiumIntervals.size());}Collections.sort(renderIntervals);if(!renderIntervals.isEmpty()){report.addProperty("frameIntervalP50Millis",renderIntervals.get(renderIntervals.size()/2));report.addProperty("frameIntervalP95Millis",renderIntervals.get((int)(renderIntervals.size()*.95)));}save("client-result.json",report);closing=true;stage=99;frames=0;var mc=Minecraft.getInstance();if(mc.level!=null)mc.level.disconnect();mc.disconnect(new TitleScreen());}
    @SubscribeEvent public static void render(RenderFrameEvent.Post e){if(!Boolean.getBoolean("muxi.horse.stadiumClientQa")||stage!=5)return;long now=System.nanoTime();if(lastRender>0){double interval=(now-lastRender)/1e6;renderIntervals.add(interval);if(!captureSinceRender&&(PERF?frames>=160&&frames<=380:frames>=40&&frames<=100))podiumIntervals.add(interval);}lastRender=now;captureSinceRender=false;}
    @SubscribeEvent public static void serverTick(ServerTickEvent.Post e){if(!Boolean.getBoolean("muxi.horse.stadiumClientQa")||closing||stage<2)return;try{var p=e.getServer().getPlayerList().getPlayers().stream().findFirst().orElse(null);if(p==null)return;for(var row:GameRuntime.get(e.getServer()).snapshot(p,"").getAsJsonArray("games"))if(row.getAsJsonObject().get("id").getAsString().equals(HorseRooms.ID))nativeState=row.getAsJsonObject().getAsJsonObject("state");var level=e.getServer().getLevel(HorseCourse.STADIUM_DIMENSION);for(Entity entity:level.getAllEntities())if(entity instanceof Horse h&&h.getTags().contains(HorsePilot.MARKER)){horseId=h.getId();break;}}catch(Throwable f){error=f.toString();}}
    @SubscribeEvent public static void tick(ClientTickEvent.Post e){if(!Boolean.getBoolean("muxi.horse.stadiumClientQa")||done)return;var mc=Minecraft.getInstance();try{
        ticks++;if(ticks%40==0){var progress=new JsonObject();progress.addProperty("stage",stage);progress.addProperty("ticks",ticks);progress.addProperty("frames",frames);progress.addProperty("maidDraws",HorseClientQA.mountedMaidDraws);save("client-progress.json",progress);}
        if(stage==99){if(mc.level!=null||mc.getSingleplayerServer()!=null||++frames<40)return;report.addProperty("normalLogout",true);save("client-result.json",report);done=true;mc.stop();return;}
        if(!error.isEmpty())throw new IllegalStateException(error);if(Files.exists(Path.of("request-normal-close.json"))||ticks>9000)throw new IllegalStateException("Bounded QA deadline stage "+stage);
        if(mc.getOverlay()!=null)return;
        if(!starting){if(!(mc.screen instanceof TitleScreen))return;check(Files.exists(Path.of("HORSE_QA_ONLY")),"owned native client world");check(System.getProperty("muxi.horse.prototype")==null,"formal module available without opt-in JVM flag");starting=true;mc.options.renderDistance().set(10);mc.createWorldOpenFlows().createFreshLevel("stadium-private-qa",new LevelSettings("Stadium private QA",GameType.CREATIVE,false,Difficulty.PEACEFUL,false,new GameRules(),WorldDataConfiguration.DEFAULT),new WorldOptions(92345678L,false,false),a->a.registryOrThrow(Registries.WORLD_PRESET).getHolderOrThrow(WorldPresets.FLAT).value().createWorldDimensions(),mc.screen);return;}
        if(mc.player==null||mc.level==null||mc.screen instanceof ReceivingLevelScreen)return;frames++;HorseCefQA.poll(ticks);
        // The real APP polls games.request; subscription snapshots alone expire after ten seconds.
        if(stage>=1&&stage<=7&&ticks%40==0)TerminalGamesApi.request();
        if(stage==0){
            Class<?> registry=Class.forName("com.elfmcys.yesstevemodel.oo0o0Oooo0OOO00OOo0OO000");Map<?,?> models=(Map<?,?>)registry.getMethod("oOoo00O0o0oO0o0oO00OO0O0").invoke(null);model=models.keySet().stream().map(Object::toString).filter(k->k.contains("01_taisho_maid")).findFirst().orElse(null);if(model==null)return;Object definition=models.get(model).getClass().getMethod("oOo0OO0O0o000OO0O000oo0o").invoke(models.get(model));Map<?,?> textures=(Map<?,?>)definition.getClass().getMethod("oOOO00ooO0oOOoOOo0OoOOOo").invoke(definition);texture=textures.keySet().stream().map(Object::toString).findFirst().orElseThrow();System.setProperty("muxi.horse.model",model);System.setProperty("muxi.horse.texture",texture);report.addProperty("model",model);report.addProperty("texture",texture);next();
            serverTask(p->{var world=p.server.getLevel(SOURCE_DIMENSION);check(world!=null,"source dimension registered before room entry");for(int x=-5;x<=5;x++)for(int z=-5;z<=5;z++)world.setBlockAndUpdate(new BlockPos(x,64,z),Blocks.STONE.defaultBlockState());source=EntityType.HORSE.create(world);source.setPos(.5,65,.5);if(Boolean.getBoolean("muxi.horse.pointsQa")){check(p.getGameProfile().getName().equals("10000"),"private points fixture uses designated isolated identity");TrustedAccounts.admit(p);check(TrustedAccounts.uid(p)==10000,"real current connection admitted by isolated server QA adapter");source.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(.38);source.getAttribute(Attributes.JUMP_STRENGTH).setBaseValue(1.0);GameRuntime.get(p.server).platform.refresh(p);}source.setTamed(true);source.setAge(0);source.setNoAi(true);source.setPersistenceRequired();source.setCustomName(Component.literal("Stadium client source"));world.addFreshEntity(source);sourceId=source.getUUID();if(!p.level().dimension().equals(SOURCE_DIMENSION)){p.stopRiding();if(!p.level().dimension().equals(Level.OVERWORLD))check(p.teleportTo(p.server.overworld(),.5,65,.5,Set.of(),0,0),"QA setup uses allowed home transit before exploration destination");check(p.teleportTo(world,.5,65,.5,Set.of(),0,0)&&p.level()==world,"QA setup reaches exact source dimension through Core travel guards");}else p.teleportTo(world,.5,65,.5,0,0);check(p.startRiding(source,true),"generated source mount accepts genuine client player");});return;
        }
        if(stage==1){
            if(!ready||mc.player.getVehicle()==null)return;if(Boolean.getBoolean("muxi.horse.pointsQa")&&(!app().has("platform")||!app().getAsJsonObject("platform").get("available").getAsBoolean()))return;var g=game();if(g==null)return;
            if(!appVerified){check(g.has("ui")&&g.getAsJsonObject("ui").has("lobby"),"dynamic APP lobby exposes horse module and declarative UI over real network");check(app().get("actionSupported").getAsBoolean(),"terminal action payload available on genuine client connection");save("app-lobby.json",app());appVerified=true;}
            if(HorseCefQA.ENABLED){if(!HorseCefQA.create())return;check(true,"actual CEF wizard selects horse game, arena and fifth difficulty through unchanged native bridge");}
            else {var config=new JsonObject();config.addProperty("mode","obstacle");config.addProperty("map",HorseStadium.ID);config.addProperty("difficulty","5");TerminalGamesApi.submit(HorseRooms.ID,"createConfigured",config.toString());}
            next();return;
        }
        if(stage==2){var r=room();if(r==null||!r.get("phase").getAsString().equals("WAITING")||frames<8)return;check(r.get("course").getAsString().equals(HorseStadium.ID)&&r.get("enemyTier").getAsInt()==5,"terminal API serializes mode/map/difficulty into oval waiting room");check(mc.level.dimension().equals(SOURCE_DIMENSION)&&mc.player.getVehicle().getUUID().equals(sourceId),"waiting room leaves actual player on original horse");if(HorseCefQA.ENABLED){if(!HorseCefQA.waitingReady())return;shot("app-native-waiting");}save("app-waiting.json",app());next();return;}
        if(stage==3){var r=room();if(r==null||r.get("enemyTier").getAsInt()!=5||frames<8)return;check(true,"terminal API configures applicable five-tier opponent before start");if(HorseCefQA.ENABLED){if(!HorseCefQA.start())return;}else TerminalGamesApi.submit(HorseRooms.ID,"start","");next();return;}
        if(stage==4){var r=room();if(r==null){if(admissionStalled&&ready)throw new IllegalStateException("Admission cache expiration automatically removed the race room during scene loading");return;}
            if(Boolean.getBoolean("muxi.horse.admissionStallQa")&&!admissionStalled&&r.get("phase").getAsString().equals("BUILDING")){admissionStalled=true;serverTask(p->{try{Files.writeString(Path.of("admission-outage.json"),"{}");GameRuntime.get(p.server).platform.refresh(p);Thread.sleep(17000);Files.deleteIfExists(Path.of("admission-outage.json"));}catch(Exception interrupted){throw new IllegalStateException(interrupted);}check(GameRuntime.get(p.server).memberships.owner(p.getUUID())!=null,"race ownership survives a scene load longer than admission TTL");});report.addProperty("admissionStallMillis",17000);return;}if(r.get("phase").getAsString().equals("BUILDING")&&frames%20==0)save("app-building.json",app());if(r.get("phase").getAsString().equals("BUILD_FAILED"))throw new IllegalStateException("Scene generation failed");if(HorseCefQA.ENABLED&&r.get("phase").getAsString().equals("BUILDING")&&!buildingShot){shot("app-native-building");buildingShot=true;}if(!mc.level.dimension().equals(HorseCourse.STADIUM_DIMENSION))return;HorseCefQA.dismiss();check(mc.player.position().distanceTo(HorseStadium.podium(0,0))<1,"genuine client starts at default presidential podium");report.addProperty("podiumX",mc.player.getX());report.addProperty("podiumY",mc.player.getY());report.addProperty("podiumZ",mc.player.getZ());next();return;}
        if(stage==5){
            if(mc.level.dimension().equals(HorseCourse.STADIUM_DIMENSION)){
                if(frames==80)save("app-running.json",app());
                if(frames==100)shot("stadium-default-podium");if(PERF&&frames==400)shot("stadium-stable-default-podium");
                if(!PERF&&frames>100&&frames<=180){look(40,108,-58,0,66,0);if(frames==180)shot("stadium-architectural-overview");}
                if(!PERF&&frames>180&&frames<=220){look(11,85,-60,0,82,-66);if(frames==210)shot("stadium-presidential-seats");}
                if(!PERF&&frames>220){Entity horse=mc.level.getEntity(horseId);if(horse!=null){look(horse.getX()+5,horse.getY()+4,horse.getZ()+7,horse.getX(),horse.getY()+1.5,horse.getZ());if(frames==300)shot("stadium-rider-track-detail");}}
                if(!PERF&&frames%15==0&&shots<80){Files.createDirectories(Path.of("race-frames"));shot("race-frames/frame-"+String.format(Locale.ROOT,"%03d",shots++));}
            }
            var r=room();if(r==null||!r.get("phase").getAsString().equals("FINISHED"))return;report.add("race",r.deepCopy());save("app-finished.json",app());next();serverTask(p->{var restored=p.server.getLevel(SOURCE_DIMENSION).getEntity(sourceId);check(restored instanceof Horse&&p.getVehicle()==restored&&p.getVehicle().getUUID().equals(sourceId)&&!HorseReturn.pending(p),"terminal-started race restores same genuine source mount UUID");check(restored.isAlive()&&restored.level().dimension().equals(SOURCE_DIMENSION),"source asset remains alive in original dimension");long originals=0;for(var level:p.server.getAllLevels())for(Entity entity:level.getAllEntities())if(entity.getUUID().equals(sourceId)&&!entity.isRemoved())originals++;check(originals==1,"source horse UUID exists exactly once after cross-dimension return");for(var result:nativeState.getAsJsonArray("rooms").get(0).getAsJsonObject().getAsJsonArray("results")){var v=result.getAsJsonObject();check(v.get("finished").getAsBoolean()&&!v.get("dnf").getAsBoolean(),"native vanilla horse finishes oval and three obstacles");
                    int recoveries=v.get("recoveries").getAsInt();
                    check(recoveries<=3&&v.get("penaltyTicks").getAsInt()==80*recoveries&&v.get("ticks").getAsInt()==v.get("rawTicks").getAsInt()+v.get("penaltyTicks").getAsInt(),"bounded checkpoint recoveries charge exact four second penalties");
                    check(v.getAsJsonArray("recoveryEvents").size()==recoveries,"each recovery has a recorded cause and checkpoint");
                    for(var trace:v.getAsJsonArray("recoveryEvents")){var recovery=trace.getAsJsonObject();check(recovery.get("restored").getAsBoolean()&&Set.of("stuck","below_track","water").contains(recovery.get("reason").getAsString())&&recovery.get("returnY").getAsDouble()>=62&&recovery.get("returnGate").getAsInt()<=recovery.get("gate").getAsInt(),"recovery returns to earlier safe checkpoint with explicit cause");}}});return;
        }
        if(stage==6){if(Boolean.getBoolean("muxi.horse.pointsQa")){var balance=app().getAsJsonObject("platform");if(!balance.get("available").getAsBoolean()||!balance.get("points").getAsString().equals("10")||app().get("resultPending").getAsInt()!=0)return;check(app().getAsJsonObject("lastResult").get("score").getAsInt()==10&&app().getAsJsonObject("lastResult").get("win").getAsBoolean(),"native champion result queued and acknowledged as ten existing points");report.add("settledPlatform",balance.deepCopy());save("app-points-acknowledged.json",app());}if(!ready||!mc.level.dimension().equals(SOURCE_DIMENSION)||mc.player.getVehicle()==null)return;check(HorseClientQA.mountedMaidDraws>100,"actual mounted Wine Fox YSM geometry rendered throughout race");if(HorseCefQA.ENABLED){if(!HorseCefQA.resultsReady())return;shot("app-native-results");check(true,"actual CEF displays settled native race times and safe exit control");HorseCefQA.leave();}else{shot("stadium-returned-original-horse");TerminalGamesApi.submit(HorseRooms.ID,"leave","");}next();return;}
        if(stage==7&&frames>50){if(!app().get("activeGame").getAsString().isEmpty())return;check(true,"terminal API exit releases room membership");save("app-exited.json",app());if(HorseCefQA.ENABLED)shot("app-native-exited");close(true,"");}
    }catch(Throwable f){try{close(false,f.toString());}catch(Throwable nested){nested.printStackTrace();mc.stop();}}}
}
